#!/bin/bash
# Generated by v32c++ from the source's own cart hints and command line. Edit
# the source (or use --no-build-scripts and keep a hand-written script)
# rather than this file: it is rewritten on every v32c++ run.

abort_build()
{
    echo
    echo BUILD FAILED
    exit 1
}

# the tools this build needs
need_tool()
{
    command -v "$1" >/dev/null 2>&1 || { echo "ERROR: $1 is needed to build, but was not found in PATH"; abort_build; }
}

need_tool v32c++
need_tool compile
need_tool assemble
need_tool packrom

# the optimizer is optional: without it only the regular build is made
HAVE_OPT=0
if command -v v32opt >/dev/null 2>&1; then
    HAVE_OPT=1
else
    echo "note: v32opt not found in PATH -- skipping the optimized (Opt) build"
fi

# create the output folders, since the development tools will not
mkdir -p bin
mkdir -p ../../../../../tmp/tmp.qp1INpYWKz

echo
echo Transpile to Vircon32 C
echo --------------------------
v32c++ --line-markers --no-build-scripts -o ../../../../../tmp/tmp.qp1INpYWKz/lm.c line_markers.cpp || abort_build

echo
echo Compile the C code
echo --------------------------
compile ../../../../../tmp/tmp.qp1INpYWKz/lm.c -o ../../../../../tmp/tmp.qp1INpYWKz/lm.asm || abort_build
if [ "$HAVE_OPT" = 1 ]; then
    v32opt -O3 ../../../../../tmp/tmp.qp1INpYWKz/lm.asm -o ../../../../../tmp/tmp.qp1INpYWKz/lmOpt.asm || abort_build
fi

echo
echo Assemble the ASM code
echo --------------------------
assemble ../../../../../tmp/tmp.qp1INpYWKz/lm.asm -o ../../../../../tmp/tmp.qp1INpYWKz/lm.vbin || abort_build
if [ "$HAVE_OPT" = 1 ]; then
    assemble ../../../../../tmp/tmp.qp1INpYWKz/lmOpt.asm -o ../../../../../tmp/tmp.qp1INpYWKz/lmOpt.vbin || abort_build
fi

echo
echo Pack the ROM
echo --------------------------
packrom ../../../../../tmp/tmp.qp1INpYWKz/lm.xml -o bin/lm.v32 || abort_build
if [ "$HAVE_OPT" = 1 ]; then
    packrom ../../../../../tmp/tmp.qp1INpYWKz/lmOpt.xml -o bin/lmOpt.v32 || abort_build
fi

echo
echo BUILD SUCCESSFUL
